{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "The closest morphine-scaffold analogue, dihydromorphine, showed essentially no CNS accumulation in mice by whole-body autoradiography; the query adds a polar glucuronide, so this direct opioid evidence supports poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Mefenamic acid glucuronide showed negligible brain uptake in rats after oral dosing, demonstrating that glucuronide conjugation generally prevents meaningful BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Naloxegol, a peripherally restricted opioid-related derivative, exhibited only 15% CSF/plasma ratio in rats, supporting poor CNS access for polar opioid-related structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The glucuronide GAZT had a CSF/plasma ratio of 0.04 in monkeys, 10-fold lower than the parent nucleoside, directly showing that glucuronide conjugation impairs CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Naloxone methiodide, a permanently charged opioid analogue, was undetectable in rat CNS after IV dosing, supporting that ionized/polar opioid derivatives fail to cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Quercetin-3-O-glucuronide was detected in perfused rat brain, providing a contradictory example that some glucuronides can achieve brain exposure, likely via deconjugation or transporter-mediated uptake; low structural similarity limits transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a morphine glucuronide with a carboxylic acid and multiple polar hydroxyls. Direct evidence from the closest morphine analogue and from multiple glucuronide conjugates consistently shows poor BBB penetration, while the single contradictory glucuronide example is structurally distant and mechanistically different. Overall, meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct in vivo brain or CSF measurement for the exact query molecule is available.",
    "Possible contribution of efflux transporters or slow deconjugation in the CNS is not directly quantified.",
    "Chronic high-dose exposure might produce low but measurable CNS levels, but this would not constitute meaningful acute access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

